const nav=document.querySelector('.nav');const menu=document.querySelector('.menu');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open)});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
const io=new IntersectionObserver(entries=>entries.forEach((e,i)=>{if(e.isIntersecting){setTimeout(()=>e.target.classList.add('visible'),Math.min(i*70,280));io.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>io.observe(el));
const stages=['Received','Validated','Planned'];const nodes=[...document.querySelectorAll('.node')];let active=0;setInterval(()=>{nodes.forEach((n,i)=>n.classList.toggle('active',i===active));active=(active+1)%nodes.length},1300);
